 for this response","format":"int32","maximum":200,"minimum":1,"type":"integer"},"totalItems":{"description":"Exact number of instances in the caller's owned scope; int64-as-string per API_SPEC.md section 13.6","format":"int64","pattern":"^[0-9]+$","type":"string","x-sdkwork-int64-string":true},"totalPages":{"description":"ceil(totalItems / pageSize); 0 when the scope is empty","format":"int32","minimum":0,"type":"integer"}},"required":["mode"],"type":"object"},"ProblemDetail":{"additionalProperties":true,"properties":{"code":{"description":"Numeric error result code; MUST be non-zero (API_SPEC.md section 15.3)","format":"int32","maximum":79999,"minimum":40001,"type":"integer"},"detail":{"type":"string"},"instance":{"description":"Request endpoint occurrence: {METHOD} {routeTemplate}","type":"string"},"operationId":{"type":"string"},"status":{"maximum":599,"minimum":100,"type":"integer"},"title":{"type":"string"},"traceId":{"format":"uuid","type":"string"},"type":{"format":"uri-reference","type":"string"}},"required":["type","title","status","code","traceId"],"type":"object"},"SandboxInstance":{"additionalProperties":false,"properties":{"createdAt":{"format":"date-time","type":"string"},"sandboxInstanceAutoStart":{"type":"boolean"},"sandboxInstanceBaseImage":{"maxLength":256,"minLength":1,"type":"string"},"sandboxInstanceDiskMb":{"format":"int32","maximum":1048576,"minimum":1024,"type":"integer"},"sandboxInstanceExpiresAt":{"format":"date-time","type":"string"},"sandboxInstanceId":{"$ref":"#/components/schemas/SandboxInstanceId"},"sandboxInstanceMemoryMb":{"format":"int32","maximum":262144,"minimum":256,"type":"integer"},"sandboxInstanceMinimumAssurance":{"$ref":"#/components/schemas/SandboxIsolationAssurance"},"sandboxInstanceName":{"maxLength":128,"minLength":1,"type":"string"},"sandboxInstanceOwnerId":{"$ref":"#/components/schemas/SandboxOwnerId"},"sandboxInstanceProfile":{"$ref":"#/components/schemas/SandboxInstanceProfile"},"sandboxInstanceRequiredCapabilities":{"default":[],"items":{"$ref":"#/components/schemas/SandboxRuntimeCapability"},"maxItems":32,"type":"array","uniqueItems":true},"sandboxInstanceState":{"$ref":"#/components/schemas/SandboxInstanceState"},"sandboxInstanceVcpuCount":{"format":"int32","maximum":64,"minimum":1,"type":"integer"},"sandboxVersion":{"$ref":"#/components/schemas/SandboxVersion"},"sandboxWorkspaceId":{"maxLength":128,"minLength":1,"type":"string"},"updatedAt":{"format":"date-time","type":"string"}},"required":["sandboxInstanceId","sandboxInstanceOwnerId","sandboxInstanceName","sandboxInstanceState","sandboxInstanceProfile","sandboxInstanceBaseImage","sandboxInstanceVcpuCount","sandboxInstanceMemoryMb","sandboxInstanceDiskMb","sandboxInstanceMinimumAssurance","sandboxInstanceAutoStart","sandboxVersion"],"type":"object"},"SandboxInstanceId":{"maxLength":128,"minLength":1,"type":"string"},"SandboxInstanceItemResponse":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"$ref":"#/components/schemas/SandboxInstanceResourceData"}},"type":"object"}]},"SandboxInstanceListResponse":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"$ref":"#/components/schemas/SandboxInstancePageData"}},"type":"object"}]},"SandboxInstancePageData":{"additionalProperties":false,"properties":{"items":{"items":{"$ref":"#/components/schemas/SandboxInstance"},"type":"array"},"pageInfo":{"$ref":"#/components/schemas/OffsetPageInfo"}},"required":["items","pageInfo"],"type":"object"},"SandboxInstanceProfile":{"enum":["standard","memory_optimized","compute_optimized"],"type":"string"},"SandboxInstanceResourceData":{"additionalProperties":false,"properties":{"item":{"$ref":"#/components/schemas/SandboxInstance"}},"required":["item"],"type":"object"},"SandboxInstanceState":{"enum":["requested","active","suspended","terminated","failed"],"type":"string"},"SandboxIsolationAssurance":{"enum":["host_user","container","user_space_kernel","micro_vm","dedicated_vm"],"typ